message.content:
{
  "title": "The Glass Diver's Escape",
  "gate_token": "8aA-o19YpudMOWiqZkedTw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers approach the ruined city.",
      "visual_description": "A vast ruined city with shattered towers and torn royal banners flapping in the wind. The glass diver peers through a spyglass from a hilltop, while Mara studies a worn map.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara spots a patrol of armored figures near the main gate.",
      "visual_description": "Mara points toward the immense castle gates, where several figures in dull armor march in formation. The tin fox hides behind a broken wall, its blue eyes glowing.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower.",
      "visual_description": "Inside a crumbling courtyard, the oracle lamp flickers, its single eye showing a vision of a twisted spire. The glass diver listens intently.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "They find the sleeping tax collector blocking a passage.",
      "visual_description": "A narrow alley is blocked by a dozing figure slumped against a wall, using a ledger as a pillow. Stamped papers flutter from his sleeves. The tin fox sniffs at him.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara diverts the patrol by sending the tin fox.",
      "visual_description": "The tin fox scurries across a cobblestone street, clattering loudly. The armored patrol turns and chases it away from the group's hiding spot.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a stained-glass window.",
      "visual_description": "Near a chapel ruin, the glass diver's helmet glimmers as he passes through a colorful window, emerging inside a dark chamber. Mara follows through the frame.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Inside a treasure room, the oracle lamp warns of a trap.",
      "visual_description": "Golden light reflects off scattered coins. The oracle lamp's eye widens as it senses a pressure plate. The glass diver freezes mid-step.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "They pass a mirror door that shows tempting illusions.",
      "visual_description": "A tall mirror door reflects a peaceful garden, but Mara's compass needle spins wildly. The glass diver touches the glass, feeling a cold pull.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox disables a magical lock.",
      "visual_description": "The tin fox inserts its key-wind tail into a glowing lock on a heavy door. Gears whir and the door swings open with a click.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is found again, still napping.",
      "visual_description": "In a collapsed library, the tax collector snores on a pile of dusty scrolls. Stamped papers have scattered around him like autumn leaves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara reads a secret passage from an old map.",
      "visual_description": "Mara unrolls a cracked parchment under the light of the oracle lamp, tracing a route through the palace ruins. The glass diver looks over her shoulder.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "They descend into a dark cellar to avoid patrols.",
      "visual_description": "A stone stairway leads down into darkness. The oracle lamp casts a dim glow, revealing cobwebs and broken barrels.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox finds a key under a loose tile.",
      "visual_description": "The tin fox's metal claws scrape at a floor tile, uncovering a small iron key. Its blue eyes flash proudly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver swims through a locked magic door.",
      "visual_description": "A door with swirling runes stands before them. The glass diver presses his helmet against it and passes through, unlocking it from the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "They reach the central courtyard, but armored patrols are everywhere.",
      "visual_description": "The group peers out from an archway. Armored figures march in formation, their boots echoing on the stones. The oracle lamp dims its light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector is used as a diversion.",
      "visual_description": "Mara props the still-sleeping tax collector against a barrel and rolls him into the open. The patrol stops to investigate the snoring figure.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the old bridge to escape.",
      "visual_description": "A crumbling stone bridge spans a ravine. The group sprints across as patrol shouts rise behind them. The tin fox's tail winds furiously.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them, sealing their escape.",
      "visual_description": "The bridge crumbles into the chasm as the last member steps onto safe ground. Dust rises, and the ruin is left behind. The oracle lamp's flame steadies.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

